    "pageFunction": "async function pageFunction(context) {
    const { $, request, log } = context;
    const jobs = [];

    const CUTOFF_DAYS = 1;
    const now = new Date();
    const cutoffDate = new Date(now.getTime() - CUTOFF_DAYS * 24 * 60 * 60 * 1000);

    const CATEGORY_MAP = {
        '1': 'Administration/Management',
        '2': 'Finance, Statistics',
        '3': 'Sales/Procurement',
        '4': 'PR/Marketing',
        '5': 'General Technical Staff',
        '19': 'Logistics/Transport/Distribution',
        '11': 'Construction/Repair',
        '10': 'Cleaning',
        '9': 'Security/Safety',
        '6': 'IT/Programming',
        '17': 'Media/Publishing',
        '8': 'Education',
        '13': 'Law',
        '7': 'Medicine/Pharmacy',
        '20': 'Beauty/Fashion',
        '18': 'Food',
        '16': 'Other',
    };

    const cidMatch = request.url.match(/[?&]cid=(\d+)/);
    const jobCategory = cidMatch ? (CATEGORY_MAP[cidMatch[1]] || `Unknown (cid=${cidMatch[1]})`) : null;

    function parseJobsGeDate(text) {
        if (!text) return null;
        const months = {
            იანვარი: 0, თებერვალი: 1, მარტი: 2, აპრილი: 3, მაისი: 4, ივნისი: 5,
            ივლისი: 6, აგვისტო: 7, სექტემბერი: 8, ოქტომბერი: 9, ნოემბერი: 10, დეკემბერი: 11,
            January: 0, February: 1, March: 2, April: 3, May: 4, June: 5,
            July: 6, August: 7, September: 8, October: 9, November: 10, December: 11,
        };
        const match = text.trim().match(/^(\d{1,2})\s+(\S+)$/);
        if (!match) return null;
        const day = parseInt(match[1], 10);
        const month = months[match[2]];
        if (month === undefined) return null;

        let year = now.getFullYear();
        let d = new Date(year, month, day);
        if (d.getTime() > now.getTime() + 24 * 60 * 60 * 1000) {
            d = new Date(year - 1, month, day);
        }
        return d;
    }

    let oldestJobOnPageIsTooOld = false;

    $('table tr').each((i, el) => {
        const link = $(el).find("a[href*='view=jobs&id=']").first();
        const href = link.attr('href');
        if (!href) return;

        const idMatch = href.match(/id=(\d+)/);
        const jobId = idMatch ? idMatch[1] : null;
        if (!jobId) return;

        const title = link.clone().children().remove().end().text().trim();

        const companyLink = $(el).find("a[href*='view=client']").last();
        const company = companyLink.text().trim();
        const companyUrl = companyLink.attr('href')
            ? 'https://jobs.ge' + companyLink.attr('href')
            : null;

        // Find date-like cells by pattern instead of fixed index,
        // since row structure (extra logo cells etc.) isn't uniform
        const cells = $(el).find('td');
        const dateTexts = [];
        cells.each((j, cell) => {
            const text = $(cell).text().trim();
            if (/^\d{1,2}\s+\S+$/.test(text) && text.length < 25) {
                dateTexts.push(text);
            }
        });
        const postedDateText = dateTexts[0] || '';
        const deadlineDate = dateTexts[1] || '';

        const postedDateParsed = parseJobsGeDate(postedDateText);

        if (postedDateParsed && postedDateParsed < cutoffDate) {
            oldestJobOnPageIsTooOld = true;
            return;
        }

        jobs.push({
            job_id: jobId,
            url: 'https://jobs.ge/en/?view=jobs&id=' + jobId,
            title,
            company,
            company_url: companyUrl,
            job_category: jobCategory,
            posted_date: postedDateText,
            deadline_date: deadlineDate,
            scraped_at: new Date().toISOString(),
        });
    });

    if (oldestJobOnPageIsTooOld) {
        log.info(`Reached jobs older than ${CUTOFF_DAYS} days on ${request.url} — later pages will be skipped by the crawler's own page limit.`);
    }

    return jobs;
}",
