  "pageFunction": "async function pageFunction(context) {
    const { $, request } = context;

    const idMatch = request.url.match(/id=(\d+)/);
    const jobId = idMatch ? idMatch[1] : null;

    let contentCell = $('table.dtable td[style*="padding-top"]').first();

    if (contentCell.length === 0) {
        let maxLen = 0;
        $('table.dtable td').each((i, el) => {
            const len = $(el).text().trim().length;
            if (len > maxLen) {
                maxLen = len;
                contentCell = $(el);
            }
        });
    }

    const externalLink = contentCell.find('a[href^="http"]').first();
    const externalApplyUrl = externalLink.attr('href') || null;
    const description = contentCell.text().replace(/\s+/g, ' ').trim();

    return [{
        job_id: 'jobsge-' + jobId,
        description: description,
        has_stub_only: !!externalApplyUrl && description.length < 300,
        external_apply_url: externalApplyUrl,
        scraped_at: new Date().toISOString()
    }];
}"
}

