function parseJobsGeDate(text) {
  if (!text) return null;
  const months = { '\u10D8\u10D0\u10DC\u10D5\u10D0\u10E0\u10D8': 0, '\u10D7\u10D4\u10D1\u10D4\u10E0\u10D5\u10D0\u10DA\u10D8': 1, '\u10DB\u10D0\u10E0\u10E2\u10D8': 2, '\u10D0\u10DE\u10E0\u10D8\u10DA\u10D8': 3, '\u10DB\u10D0\u10D8\u10E1\u10D8': 4, '\u10D8\u10D5\u10DC\u10D8\u10E1\u10D8': 5, '\u10D8\u10D5\u10DA\u10D8\u10E1\u10D8': 6, '\u10D0\u10D2\u10D5\u10D8\u10E1\u10E2\u10DD': 7, '\u10E1\u10D4\u10E5\u10E2\u10D4\u10DB\u10D1\u10D4\u10E0\u10D8': 8, '\u10DD\u10E5\u10E2\u10DD\u10DB\u10D1\u10D4\u10E0\u10D8': 9, '\u10DC\u10DD\u10D4\u10DB\u10D1\u10D4\u10E0\u10D8': 10, '\u10D3\u10D4\u10D9\u10D4\u10DB\u10D1\u10D4\u10E0\u10D8': 11, January: 0, February: 1, March: 2, April: 3, May: 4, June: 5, July: 6, August: 7, September: 8, October: 9, November: 10, December: 11 };
  const m = text.trim().match(/^(\d{1,2})\s+(\S+)$/);
  if (!m) return null;
