function formatDate(d) {
  if (!d || isNaN(d.getTime())) return '';
  const pad = n => String(n).padStart(2, '0');
  return `'${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function parseRelative(text, anchor) {
  if (!text || typeof text !== 'string') return null;
  const m = text.match(/(\d+)\s*(minute|hour|day|week|month)s?\s*ago/i);
  if (!m) return null;
  const n = parseInt(m[1], 10);
  const unit = m[2].toLowerCase();
  const d = new Date(anchor.getTime());
  if (unit === 'minute') d.setMinutes(d.getMinutes() - n);
  else if (unit === 'hour') d.setHours(d.getHours() - n);
  else if (unit === 'day') d.setDate(d.getDate() - n);
  else if (unit === 'week') d.setDate(d.getDate() - n * 7);
  else if (unit === 'month') d.setMonth(d.getMonth() - n);
  return d;
}

function salaryInfoToText(raw) {
  if (!raw) return '';
  if (typeof raw === 'string') return raw;
  if (Array.isArray(raw)) {
    return raw.map(x => typeof x === 'string' ? x : JSON.stringify(x)).join(' ');
  }
  if (typeof raw === 'object') return JSON.stringify(raw);
  return String(raw);
}

function parseSalary(rawText) {
  const text = salaryInfoToText(rawText);
  if (!text) return { min: '', max: '', currency: '' };
  let currency = '';
  const cm = text.match(/(\$|USD|EUR|GBP|GEL)/i);
  if (cm) {
    const map = { '$': 'USD' };
    currency = map[cm[1]] || cm[1].toUpperCase();
  }
  const nums = text.match(/[\d,]+(?:\.\d+)?/g);
  if (!nums || nums.length === 0) return { min: '', max: '', currency };
  const isK = /k\b/i.test(text);
  const parsed = nums.map(n => {
    const v = parseFloat(n.replace(/,/g, ''));
    return isK ? v * 1000 : v;
  });
  if (parsed.length === 1) return { min: parsed[0], max: parsed[0], currency };
  return { min: Math.min(...parsed), max: Math.max(...parsed), currency };
}

return $input.all().map(item => {
  const d = item.json;
  const scrapedAt = new Date();
  let parsedDate = d.publishedAt ? new Date(d.publishedAt) : null;
  if (!parsedDate || isNaN(parsedDate.getTime())) parsedDate = parseRelative(d.postedTime, scrapedAt);
  const sal = parseSalary(d.salaryInfo);
  const workTypeRemote = d.workType ? /remote/i.test(d.workType) : '';
  return { json: {
    job_id: `linkedin-${d.jobId}`,
    source: 'linkedin',
    scraper: 'linkedin-cheap-scraper',
    title: d.jobTitle || '',
    company: d.companyName || '',
    location: d.location || '',
    category: '',
    url: d.jobUrl || '',
    company_url: d.companyUrl || '',
    job_type: d.contractType || d.workType || '',
    is_remote: workTypeRemote === '' ? '' : (workTypeRemote ? 'true' : 'false'),
    posted_date: formatDate(parsedDate),
    deadline_date: '',
    salary_min: sal.min,
    salary_max: sal.max,
    salary_currency: sal.currency,
    description: d.jobDescription || '',
    external_apply_url: d.applyUrl || '',
    scraped_at: scrapedAt.toISOString(),
  }};
});

// Process all jobs.ge rows that don't have a description yet.
const BATCH_LIMIT = 50; // safety cap per run so a huge backlog doesn't overload one execution

const items = $input.all();

const needsDescription = items.filter(item => {
  const isJobsGe = item.json.source === 'jobs.ge';
  const hasId = !!item.json.job_id;
  const alreadyHasDescription = item.json.description && item.json.description.toString().trim().length > 0;
  return isJobsGe && hasId && !alreadyHasDescription;
});

const toProcess = needsDescription.slice(0, BATCH_LIMIT);

const startUrls = toProcess.map(item => {
  const rawId = item.json.job_id.toString().replace(/^jobsge-/, '');
  return { url: `https://jobs.ge/ge/?view=jobs&id=${rawId}` };
});

return [{ json: { startUrls, count: startUrls.length, totalPending: needsDescription.length } }];
